const express = require('express');
const { AppSettings } = require('../models');
const { requireDeveloperToken } = require('../auth');

const app = express();
app.use(express.json());

app.put('/api/apps/:appId/vapid-settings', requireDeveloperToken, async (req, res) => {
  const { appId } = req.params;
  const { vapidPublicKey, vapidPrivateKey, contactSubject } = req.body;

  const appRecord = await AppSettings.findByPk(appId);
  if (!appRecord) {
    return res.status(404).json({ error: 'Application not found' });
  }

  // Ensure the developer owns the application
  if (appRecord.developerId !== req.developer.id && !req.developer.isAdmin) {
    return res.status(403).json({ error: 'Forbidden: you do not have permission to manage this application' });
  }

  appRecord.vapidPublicKey = vapidPublicKey;
  appRecord.vapidPrivateKey = vapidPrivateKey;
  appRecord.contactSubject = contactSubject;
  await appRecord.save();

  res.json({ success: true, appId: appRecord.id, publicKey: appRecord.vapidPublicKey });
});

app.listen(8102);
